function getQuestList() {
	if (!questList) {
		questList = fs.readdirSync(questDir)
			.filter(file => file.endsWith('.json'))
			.map(file => {
				const quest = getBin(`Quest/${path.basename(file, '.json')}`);
				quest._sourceFile = path.basename(file, '.json');
				return quest;
			});
	}
	return questList;
}

function findQuestById(questId) {
	const keys = getQuestKeys();
	return getQuestList().find(quest =>
		quest[keys.questId] === questId ||
		Object.values(quest).some(value => value === questId));
}

function buildTalkFileMap() {
	if (!talkFileById) {
		const keys = getTalkKeys();
		talkFileById = new Map();
		fs.readdirSync(talkQuestDir)
			.filter(file => file.endsWith('.json'))
			.forEach(file => {
				const data = getBin(`Talk/Quest/${path.basename(file, '.json')}`);
				if (data && data[keys.talkId]) talkFileById.set(Number(data[keys.talkId]), file);
			});
	}
	return talkFileById;
}

function getTalkData(talkId) {
	if (!talkDataById) talkDataById = new Map();
	if (!talkDataById.has(talkId)) {
		const file = buildTalkFileMap().get(talkId);
		talkDataById.set(talkId, file ? getBin(`Talk/Quest/${path.basename(file, '.json')}`) : null);
	}
	return talkDataById.get(talkId);
}

function getText(language, textMapHash) {
	const text = textMapHash && language[textMapHash] ? language[textMapHash] : '';
	return text
		? sanitizer(text, replaceNewline, replaceNonBreakSpace, replaceLayoutPC, removeSprite, removeTimezone)
		: '';
}

function getNpcName(language, npcId) {
	const npc = npcById.get(String(npcId));
	return npc ? getText(language, npc.nameTextMapHash) : '';
}

function getVisibleNpcName(language, npcId) {
	const npc = npcById.get(String(npcId));
	if (!npc || npc.invisiable) return '';
	return getText(language, npc.nameTextMapHash);
}

function getChapterTitle(language, chapterId) {
	const chapter = chapterById.get(chapterId);
	return chapter ? getText(language, chapter.chapterTitleTextMapHash) : '';
}

function parseGuide(guide) {
	if (!guide) return null;

	const params = Object.values(guide)
		.find(value => Array.isArray(value) && value.some(param => typeof param === 'string' && param.startsWith('[')));
	if (!Array.isArray(params)) return null;

	return parsePositionParams(params)[0] || null;
}

function parsePositionParams(params) {
	if (!Array.isArray(params)) return [];

	return params
		.map(param => typeof param === 'string' && param.match(/^\[(\d+)(?:_(\d+))?:([^,\]]+),([^,\]]+),([^,\]]+)/))
		.filter(Boolean)
		.map(match => {
			const data = {
				sceneId: Number(match[1]),
				position: match.slice(3, 6).map(Number)
			};

			if (match[2]) data.pointId = Number(match[2]);
			return data;
		});
}

function makeDialog(language, dialog) {
	const keys = getTalkKeys();
	const speakerInfo = dialog[keys.speaker] || {};
	const roleType = speakerInfo._type || '';
	const speakerName = roleType === 'TALK_ROLE_NPC'
		? getNpcName(language, speakerInfo._id)
		: roleType === 'TALK_ROLE_PLAYER'
			? '#{NICKNAME}'
			: '';
	const speakerTitle = getText(language, dialog[keys.speakerTitle]);
	const speakerSubtitle = getText(language, dialog[keys.subtitle]);
	const data = {
		id: dialog[keys.dialogId],
		content: getText(language, dialog[keys.content]),
		roleType,
		nextDialogs: dialog[keys.next] || []
	};

	if (dialog[keys.showType]) data.showType = dialog[keys.showType];
	if (speakerName) data.speakerName = speakerName;
	if (speakerTitle) data.speakerTitle = speakerTitle;
	if (speakerSubtitle) data.speakerSubtitle = speakerSubtitle;

	return data;
}

